"""Count this session's code-research calls: tokensave versus plain text search.

Reads the newest transcript for the current directory under
~/.claude/projects/, or the transcript given as the first argument.
Run from the repo root at session close.

A plain search counts only when it looks for code: a Grep or Glob call,
or a shell command that starts with a recursive search (grep -r, rg,
git grep, or a recursive listing piped into Select-String). Searches of
docs, logs or data files, and filters on another command's output
(`... | grep x`), are not code research and are not counted.
"""
import glob
import json
import os
import re
import sys

TOOL = re.compile(r"tokensave")
BYPASS = "TOKENSAVE_BYPASS:"
NON_CODE = re.compile(r"\.(md|mdx|txt|log|json|jsonl|ya?ml|csv)\b|\b(md|json|yaml|txt)$", re.I)
SHELL_SEARCH = re.compile(r"^\s*(rg|ag|ack|git\s+grep)\s|^\s*grep\s(.*\s)?(-[a-zA-Z]*[rR]|--recursive)")
PS_LISTING = re.compile(r"^\s*(Get-ChildItem|gci|dir|ls)\s.*-Recurse", re.I)
PS_SEARCH = re.compile(r"^\s*(sls|Select-String)\s", re.I)


def unquote_separators(command):
    """Blank out | ; & and newlines inside quotes, so a search pattern like "a|b" does not split the command."""
    out, quote = [], None
    for ch in command:
        if quote:
            quote = None if ch == quote else quote
            ch = " " if ch in "|;&\n" else ch
        elif ch in "'\"":
            quote = ch
        out.append(ch)
    return "".join(out)


def shell_search(command):
    """True when a command line runs a code search of its own."""
    for part in re.split(r"&&|\|\||;|\n", unquote_separators(command)):
        stages = part.split("|")
        head = stages[0]
        if NON_CODE.search(head):
            continue
        if SHELL_SEARCH.search(head):
            return True
        if PS_LISTING.search(head) and any(PS_SEARCH.search(s) for s in stages[1:]):
            return True
    return False


def classify(name, args):
    """'research', 'fallback', 'bypass', or None for a call that is not a search."""
    if TOOL.search(name):
        return "research"
    if name in ("Grep", "Glob"):
        # Grep's pattern is the search text, Glob's is the file pattern.
        keys = ("pattern", "path") if name == "Glob" else ("path", "glob", "type")
        target = " ".join(str(args.get(k, "")) for k in keys)
        return None if NON_CODE.search(target) else "fallback"
    if name in ("Bash", "PowerShell"):
        command = args.get("command", "")
        if shell_search(command):
            return "bypass" if BYPASS in command else "fallback"
    return None


def transcript():
    if len(sys.argv) > 1:
        return sys.argv[1]
    slug = re.sub(r"[^A-Za-z0-9]", "-", os.getcwd())
    files = glob.glob(os.path.join(os.path.expanduser("~"), ".claude", "projects", slug, "*.jsonl"))
    if not files:
        sys.exit(f"No transcript found for {os.getcwd()}; run this from the repo root.")
    return max(files, key=os.path.getmtime)


def tool_calls(path):
    with open(path, encoding="utf-8") as f:
        for line in f:
            try:
                entry = json.loads(line)
            except ValueError:
                continue
            content = (entry.get("message") or {}).get("content")
            if entry.get("type") != "assistant" or not isinstance(content, list):
                continue
            for part in content:
                if isinstance(part, dict) and part.get("type") == "tool_use":
                    yield part.get("name", ""), part.get("input") or {}


def main():
    counts = {"research": 0, "fallback": 0, "bypass": 0}
    for name, args in tool_calls(transcript()):
        kind = classify(name, args)
        if kind:
            counts[kind] += 1
    total = counts["research"] + counts["fallback"]
    ratio = f"{100 * counts['research'] // total}%" if total else "n/a"
    print(f"tokensave: {counts['research']} calls, plain code searches: {counts['fallback']} "
          f"(plus {counts['bypass']} marked bypasses) -> {ratio}")


if __name__ == "__main__":
    main()

files..github/scripts/pin_check.py:
"""Lists the pinned versions in the workflows that are behind the newest releases.

Pins keep a PR's result stable; this says when they fall behind. The weekly
pin-check workflow looks up the newest releases and passes them in:

    pin_check.py --cli 2.1.310 --action-sha <40 hex> --action-version v1.0.220 FILE...

Prints a Markdown list of the pins that are behind, one line per pinned value
with every place it is pinned, or nothing when every pin is current. Exits 1 on
bad arguments or a file it cannot read.

Pins it reads:
- the CLI version a workflow installs: `CLI_VERSION: "2.1.300"` or
  `PINNED_VERSION: "2.1.299"`;
- the review action's commit: `uses: anthropics/claude-code-action@<sha>`, with
  the version it names in the comment after it.
"""

import re
import sys

CLI = re.compile(r'^\s*(?:CLI_VERSION|PINNED_VERSION):\s*"?(\d+(?:\.\d+)*)"?\s*(?:#.*)?$')
ACTION = re.compile(r"^\s*(?:-\s+)?uses:\s*anthropics/claude-code-action@([0-9a-f]{40})\b(?:\s*#\s*(.*))?$")
VERSION = re.compile(r"\d+(?:\.\d+)*")
SHA = re.compile(r"[0-9a-f]{40}")


def _tuple(version):
    return tuple(int(p) for p in version.split("."))


def pins(name, text):
    """[(kind, value, label, "file:line")] for every pin in one file."""
    found = []
    for n, line in enumerate(text.splitlines(), 1):
        m = CLI.match(line)
        if m:
            found.append(("cli", m.group(1), m.group(1), "%s:%d" % (name, n)))
            continue
        m = ACTION.match(line)
        if m:
            label = (m.group(2) or "").strip() or m.group(1)[:12]
            found.append(("action", m.group(1), label, "%s:%d" % (name, n)))
    return found


def behind(found, cli, action_sha):
    """The pins older than the newest CLI or not on the newest action commit,
    grouped by pinned value: [(kind, label, [places])] in first-seen order."""
    groups = {}
    for kind, value, label, place in found:
        old = _tuple(value) < _tuple(cli) if kind == "cli" else value != action_sha
        if old:
            groups.setdefault((kind, value), [label, []])[1].append(place)
    return [(kind, label, places) for (kind, _), (label, places) in groups.items()]


def report(stale, cli, action_version):
    newest = {"cli": "CLI " + cli, "action": "action " + action_version}
    what = {"cli": "CLI", "action": "Review action"}
    return "".join("- %s `%s` is behind the newest %s: %s\n"
                   % (what[kind], label, newest[kind], ", ".join("`%s`" % p for p in places))
                   for kind, label, places in stale)


def _option(args, name):
    if name not in args or args.index(name) + 1 == len(args):
        raise ValueError("%s needs a value" % name)
    i = args.index(name)
    value = args[i + 1]
    del args[i:i + 2]
    return value


def main(argv):
    args = list(argv)
    try:
        cli = _option(args, "--cli")
        sha = _option(args, "--action-sha")
        version = _option(args, "--action-version")
        if not VERSION.fullmatch(cli) or not SHA.fullmatch(sha) or not args:
            raise ValueError("usage: pin_check.py --cli X.Y.Z --action-sha SHA --action-version V FILE...")
        found = []
        for name in args:
            with open(name, encoding="utf-8") as fh:
                found += pins(name, fh.read())
    except (ValueError, OSError) as e:
        print("pin_check: %s" % e, file=sys.stderr)
        return 1
    sys.stdout.write(report(behind(found, cli, sha), cli, version))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
